  const contracts={standard:{id:'V-26-014',name:'Standardauftrag',volume:600,saw:360,prices:{saw:78,pulp:34,down:26},shortfallRate:2},premium:{id:'V-26-015',name:'Mehrmenge mit Preisaufschlag',volume:720,saw:460,prices:{saw:84,pulp:34,down:26},shortfallRate:6}};
  const sum=a=>a.reduce((x,y)=>x+y,0),total=g=>sum(Object.values(g)),clamp=n=>Math.max(0,Math.min(1,n)),money=n=>Math.round(n*100)/100;
  const grades=()=>({saw:0,pulp:0,down:0});
