  const COSTS={planning:120,fieldPreparation:405,tour:240,matchedDispatch:85,accessCheck:120,linkedDocs:90,failedAccess:180,reconcileLinked:80,reconcilePaper:180,closeout:120,rework:350},HAUL={tourVolume:25,maxTours:30};
  function initial(improved=false){const s=ForestGame.initial();s.phase='forest';s.journey={contractType:'standard',preparation:improved?'field':'records',documentation:improved?'digital':'paper',haulMode:'matched',access:'checked',deliveryDocs:'linked',reconciliation:'match',closeout:'document',contract:null,plan:null,logistics:null,settlement:null};return s;}
  function choose(s,key,value){const choices={contractType:['standard','premium'],preparation:['records','field'],documentation:['paper','digital'],haulMode:['matched','estimate'],access:['checked','unchecked'],deliveryDocs:['linked','paper'],reconciliation:['match','accept'],closeout:['document','force']};if(!choices[key]?.includes(value))throw Error('Ungültige Auswahl.');const allowed=s.phase==='forest'?['contractType','preparation','documentation']:s.phase==='logistics'?['haulMode','access','deliveryDocs']:s.phase==='settlement'?['reconciliation','closeout']:[];if(!allowed.includes(key))throw Error('Diese Entscheidung ist bereits abgeschlossen.');const n=structuredClone(s);n.journey[key]=value;return n;}
  function planPreview(s){const j=s.journey,costItems=[{label:'Auftragsvorbereitung und Ressourcenplanung',value:COSTS.planning}];if(j.preparation==='field')costItems.push({label:'Vorerkundung · 3 h Revierleitung und Anfahrt',value:COSTS.fieldPreparation});return{cost:sum(costItems.map(x=>x.value)),costItems};}
  function start(s){if(s.phase!=='forest'||s.journey.plan)throw Error('Die Waldplanung ist bereits abgeschlossen.');const n=structuredClone(s),j=n.journey;j.contract=structuredClone(contracts[j.contractType]);const{cost,costItems}=planPreview(n);if(j.preparation==='field'){n.boundaryChecked.a=true;n.stands.find(x=>x.id==='b').surveyCoverage=100;}if(j.documentation==='digital')Object.assign(n,{handoverMode:'digital',reporting:'live',cutting:'current'});else Object.assign(n,{handoverMode:'manual',reporting:'manual'});n.handoverAccepted={a:false,b:false,c:false};n.handoverVersions={a:0,b:0,c:0};j.plan={cost,costItems,preparation:j.preparation,documentation:j.documentation};n.cost+=cost;n.phase='plan';return n;}
